<?php

declare(strict_types=1);

namespace App\Models;

use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * One browser, subscribed to push.
 *
 * The keys here were generated by the browser and are useless without
 * the VAPID private key, which lives in the environment and never in the
 * database. Deleting a row ends the subscription; nothing else does.
 */
class PushSubscription extends Model
{
    use HasFactory;

    protected $guarded = [];

    protected function casts(): array
    {
        return ['last_used_at' => 'datetime'];
    }

    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    /** A browser that has been gone this long is not coming back. */
    public const MAX_FAILURES = 5;

    public static function hashFor(string $endpoint): string
    {
        return hash('sha256', $endpoint);
    }
}
